18	package org.apache.hadoop.hdfs.server.blockmanagement;
19	
20	import java.util.ArrayList;
21	import java.util.HashSet;
22	import java.util.Iterator;
23	import java.util.LinkedList;
24	import java.util.List;
25	import java.util.concurrent.atomic.LongAdder;
26	
27	import org.apache.hadoop.hdfs.server.namenode.NameNode;
28	import org.apache.hadoop.hdfs.util.LightWeightLinkedSet;
29	
30	/**
31	 * Keep prioritized queues of low redundant blocks.
32	 * Blocks have redundancy priority, with priority
33	 * {@link #QUEUE_HIGHEST_PRIORITY} indicating the highest priority.
34	 * </p>
35	 * Having a prioritised queue allows the {@link BlockManager} to select
36	 * which blocks to replicate first -it tries to give priority to data
37	 * that is most at risk or considered most valuable.
38	 *
39	 * <p/>
40	 * The policy for choosing which priority to give added blocks
41	 * is implemented in {@link #getPriority(BlockInfo, int, int, int, int)}.
42	 * </p>
43	 * <p>The queue order is as follows:</p>
44	 * <ol>
45	 *   <li>{@link #QUEUE_HIGHEST_PRIORITY}: the blocks that should be redundant
46	 *   first. That is blocks with only one copy, or blocks with zero live
47	 *   copies but a copy in a node being decommissioned. These blocks
48	 *   are at risk of loss if the disk or server on which they
49	 *   remain fails.</li>
50	 *   <li>{@link #QUEUE_VERY_LOW_REDUNDANCY}: blocks that are very
51	 *   under-replicated compared to their expected values. Currently
52	 *   that means the ratio of the ratio of actual:expected means that
53	 *   there is <i>less than</i> 1:3.</li>. These blocks may not be at risk,
54	 *   but they are clearly considered "important".
55	 *   <li>{@link #QUEUE_LOW_REDUNDANCY}: blocks that are also under
56	 *   replicated, and the ratio of actual:expected is good enough that
57	 *   they do not need to go into the {@link #QUEUE_VERY_LOW_REDUNDANCY}
58	 *   queue.</li>
59	 *   <li>{@link #QUEUE_REPLICAS_BADLY_DISTRIBUTED}: there are as least as
60	 *   many copies of a block as required, but the blocks are not adequately
61	 *   distributed. Loss of a rack/switch could take all copies off-line.</li>
62	 *   <li>{@link #QUEUE_WITH_CORRUPT_BLOCKS} This is for blocks that are corrupt
63	 *   and for which there are no-non-corrupt copies (currently) available.
64	 *   The policy here is to keep those corrupt blocks replicated, but give
65	 *   blocks that are not corrupt higher priority.</li>
66	 * </ol>
67	 */
68	class LowRedundancyBlocks implements Iterable<BlockInfo> {
69	  /** The total number of queues : {@value} */
70	  static final int LEVEL = 5;
71	  /** The queue with the highest priority: {@value} */
72	  static final int QUEUE_HIGHEST_PRIORITY = 0;
73	  /** The queue for blocks that are way below their expected value : {@value} */
74	  static final int QUEUE_VERY_LOW_REDUNDANCY = 1;
75	  /**
76	   * The queue for "normally" without sufficient redundancy blocks : {@value}.
77	   */
78	  static final int QUEUE_LOW_REDUNDANCY = 2;
79	  /** The queue for blocks that have the right number of replicas,
80	   * but which the block manager felt were badly distributed: {@value}
81	   */
82	  static final int QUEUE_REPLICAS_BADLY_DISTRIBUTED = 3;
83	  /** The queue for corrupt blocks: {@value} */
84	  static final int QUEUE_WITH_CORRUPT_BLOCKS = 4;
85	  /** the queues themselves */
86	  private final List<LightWeightLinkedSet<BlockInfo>> priorityQueues
87	      = new ArrayList<>(LEVEL);
88	
89	  /** The number of corrupt blocks with replication factor 1 */
90	
91	  private final LongAdder lowRedundancyBlocks = new LongAdder();
92	  private final LongAdder corruptBlocks = new LongAdder();
93	  private final LongAdder corruptReplicationOneBlocks = new LongAdder();
94	  private final LongAdder lowRedundancyECBlockGroups = new LongAdder();
95	  private final LongAdder corruptECBlockGroups = new LongAdder();
96	  private final LongAdder highestPriorityLowRedundancyReplicatedBlocks
97	      = new LongAdder();
98	  private final LongAdder highestPriorityLowRedundancyECBlocks
99	      = new LongAdder();
100	
101	  /** Create an object. */
102	  LowRedundancyBlocks() {
103	    for (int i = 0; i < LEVEL; i++) {
104	      priorityQueues.add(new LightWeightLinkedSet<BlockInfo>());
105	    }
106	  }
107	
108	  /**
109	   * Empty the queues.
110	   */
111	  synchronized void clear() {
112	    for (int i = 0; i < LEVEL; i++) {
113	      priorityQueues.get(i).clear();
114	    }
115	    lowRedundancyBlocks.reset();
116	    corruptBlocks.reset();
117	    corruptReplicationOneBlocks.reset();
118	    lowRedundancyECBlockGroups.reset();
119	    corruptECBlockGroups.reset();
120	    highestPriorityLowRedundancyReplicatedBlocks.reset();
121	    highestPriorityLowRedundancyECBlocks.reset();
122	  }
123	
124	  /** Return the total number of insufficient redundancy blocks. */
125	  synchronized int size() {
126	    int size = 0;
127	    for (int i = 0; i < LEVEL; i++) {
128	      size += priorityQueues.get(i).size();
129	    }
130	    return size;
131	  }
132	
133	  /**
134	   * Return the number of insufficiently redundant blocks excluding corrupt
135	   * blocks.
136	   */
137	  synchronized int getLowRedundancyBlockCount() {
138	    int size = 0;
139	    for (int i = 0; i < LEVEL; i++) {
140	      if (i != QUEUE_WITH_CORRUPT_BLOCKS) {
141	        size += priorityQueues.get(i).size();
142	      }
143	    }
144	    return size;
145	  }
146	
147	  /** Return the number of corrupt blocks */
148	  synchronized int getCorruptBlockSize() {
149	    return priorityQueues.get(QUEUE_WITH_CORRUPT_BLOCKS).size();
150	  }
151	
152	  /** Return the number of corrupt blocks with replication factor 1 */
153	  long getCorruptReplicationOneBlockSize() {
154	    return getCorruptReplicationOneBlocks();
155	  }
156	
157	  /**
158	   * Return under replicated block count excluding corrupt replicas.
159	   */
160	  long getLowRedundancyBlocks() {
161	    return lowRedundancyBlocks.longValue() - getCorruptBlocks();
162	  }
163	
164	  long getCorruptBlocks() {
165	    return corruptBlocks.longValue();
166	  }
167	
168	  long getCorruptReplicationOneBlocks() {
169	    return corruptReplicationOneBlocks.longValue();
170	  }
171	
172	  /** Return the number of under replicated blocks
173	   * with the highest priority to recover */
174	  long getHighestPriorityReplicatedBlockCount() {
175	    return highestPriorityLowRedundancyReplicatedBlocks.longValue();
176	  }
177	
178	  /** Return the number of under replicated EC blocks
179	   * with the highest priority to recover */
180	  long getHighestPriorityECBlockCount() {
181	    return highestPriorityLowRedundancyECBlocks.longValue();
182	  }
183	
184	  /**
185	   *  Return low redundancy striped blocks excluding corrupt blocks.
186	   */
187	  long getLowRedundancyECBlockGroups() {
188	    return lowRedundancyECBlockGroups.longValue() -
189	        getCorruptECBlockGroups();
190	  }
191	
192	  long getCorruptECBlockGroups() {
193	    return corruptECBlockGroups.longValue();
194	  }
195	
196	  /** Check if a block is in the neededReconstruction queue. */
197	  synchronized boolean contains(BlockInfo block) {
198	    for(LightWeightLinkedSet<BlockInfo> set : priorityQueues) {
199	      if (set.contains(block)) {
200	        return true;
201	      }
202	    }
203	    return false;
204	  }
205	
206	  /** Return the priority of a block
207	   * @param curReplicas current number of replicas of the block
208	   * @param expectedReplicas expected number of replicas of the block
209	   * @return the priority for the blocks, between 0 and ({@link #LEVEL}-1)
210	   */
211	  private int getPriority(BlockInfo block,
212	                          int curReplicas,
213	                          int readOnlyReplicas,
214	                          int outOfServiceReplicas,
215	                          int expectedReplicas) {
216	    assert curReplicas >= 0 : "Negative replicas!";
217	    if (curReplicas >= expectedReplicas) {
218	      // Block has enough copies, but not enough racks
219	      return QUEUE_REPLICAS_BADLY_DISTRIBUTED;
220	    }
221	    if (block.isStriped()) {
222	      BlockInfoStriped sblk = (BlockInfoStriped) block;
223	      return getPriorityStriped(curReplicas, outOfServiceReplicas,
224	          sblk.getRealDataBlockNum(), sblk.getParityBlockNum());
225	    } else {
226	      return getPriorityContiguous(curReplicas, readOnlyReplicas,
227	          outOfServiceReplicas, expectedReplicas);
228	    }
229	  }
230	
231	  private int getPriorityContiguous(int curReplicas, int readOnlyReplicas,
232	      int outOfServiceReplicas, int expectedReplicas) {
233	    if (curReplicas == 0) {
234	      // If there are zero non-decommissioned replicas but there are
235	      // some out of service replicas, then assign them highest priority
236	      if (outOfServiceReplicas > 0) {
237	        return QUEUE_HIGHEST_PRIORITY;
238	      }
239	      if (readOnlyReplicas > 0) {
240	        // only has read-only replicas, highest risk
241	        // since the read-only replicas may go down all together.
242	        return QUEUE_HIGHEST_PRIORITY;
243	      }
244	      //all we have are corrupt blocks
245	      return QUEUE_WITH_CORRUPT_BLOCKS;
246	    } else if (curReplicas == 1) {
247	      // only one replica, highest risk of loss
248	      // highest priority
249	      return QUEUE_HIGHEST_PRIORITY;
250	    } else if ((curReplicas * 3) < expectedReplicas) {
251	      //can only afford one replica loss
252	      //this is considered very insufficiently redundant blocks.
253	      return QUEUE_VERY_LOW_REDUNDANCY;
254	    } else {
255	      //add to the normal queue for insufficiently redundant blocks
256	      return QUEUE_LOW_REDUNDANCY;
257	    }
258	  }
259	
260	  private int getPriorityStriped(int curReplicas, int outOfServiceReplicas,
261	      short dataBlkNum, short parityBlkNum) {
262	    if (curReplicas < dataBlkNum) {
263	      // There are some replicas on decommissioned nodes so it's not corrupted
264	      if (curReplicas + outOfServiceReplicas >= dataBlkNum) {
265	        return QUEUE_HIGHEST_PRIORITY;
266	      }
267	      return QUEUE_WITH_CORRUPT_BLOCKS;
268	    } else if (curReplicas == dataBlkNum) {
269	      // highest risk of loss, highest priority
270	      return QUEUE_HIGHEST_PRIORITY;
271	    } else if ((curReplicas - dataBlkNum) * 3 < parityBlkNum + 1) {
272	      // can only afford one replica loss
273	      // this is considered very insufficiently redundant blocks.
274	      return QUEUE_VERY_LOW_REDUNDANCY;
275	    } else {
276	      // add to the normal queue for insufficiently redundant blocks.
277	      return QUEUE_LOW_REDUNDANCY;
278	    }
279	  }
280	
281	  /**
282	   * Add a block to insufficiently redundant queue according to its priority.
283	   *
284	   * @param block a low redundancy block
285	   * @param curReplicas current number of replicas of the block
286	   * @param outOfServiceReplicas the number of out-of-service replicas
287	   * @param expectedReplicas expected number of replicas of the block
288	   * @return true if the block was added to a queue.
289	   */
290	  synchronized boolean add(BlockInfo block,
291	      int curReplicas, int readOnlyReplicas,
292	      int outOfServiceReplicas, int expectedReplicas) {
293	    final int priLevel = getPriority(block, curReplicas, readOnlyReplicas,
294	        outOfServiceReplicas, expectedReplicas);
295	    if(add(block, priLevel, expectedReplicas)) {
296	      NameNode.blockStateChangeLog.debug(
297	          "BLOCK* NameSystem.LowRedundancyBlock.add: {}"
298	              + " has only {} replicas and need {} replicas so is added to"
299	              + " neededReconstructions at priority level {}",
300	          block, curReplicas, expectedReplicas, priLevel);
301	
302	      return true;
303	    }
304	    return false;
305	  }
306	
307	  private boolean add(BlockInfo blockInfo, int priLevel, int expectedReplicas) {
308	    if (priorityQueues.get(priLevel).add(blockInfo)) {
309	      incrementBlockStat(blockInfo, priLevel, expectedReplicas);
310	      return true;
311	    }
312	    return false;
313	  }
314	
315	  private void incrementBlockStat(BlockInfo blockInfo, int priLevel,
316	      int expectedReplicas) {
317	    if (blockInfo.isStriped()) {
318	      lowRedundancyECBlockGroups.increment();
319	      if (priLevel == QUEUE_WITH_CORRUPT_BLOCKS) {
320	        corruptECBlockGroups.increment();
321	      }
322	      if (priLevel == QUEUE_HIGHEST_PRIORITY) {
323	        highestPriorityLowRedundancyECBlocks.increment();
324	      }
325	    } else {
326	      lowRedundancyBlocks.increment();
327	      if (priLevel == QUEUE_WITH_CORRUPT_BLOCKS) {
328	        corruptBlocks.increment();
329	        if (expectedReplicas == 1) {
330	          corruptReplicationOneBlocks.increment();
331	        }
332	      }
333	      if (priLevel == QUEUE_HIGHEST_PRIORITY) {
334	        highestPriorityLowRedundancyReplicatedBlocks.increment();
335	      }
336	    }
337	  }
338	
339	  /** Remove a block from a low redundancy queue. */
340	  synchronized boolean remove(BlockInfo block,
341	      int oldReplicas, int oldReadOnlyReplicas,
342	      int outOfServiceReplicas, int oldExpectedReplicas) {
343	    final int priLevel = getPriority(block, oldReplicas, oldReadOnlyReplicas,
344	        outOfServiceReplicas, oldExpectedReplicas);
345	    boolean removedBlock = remove(block, priLevel, oldExpectedReplicas);
346	    if (priLevel == QUEUE_WITH_CORRUPT_BLOCKS &&
347	        oldExpectedReplicas == 1 &&
348	        removedBlock) {
349	      assert corruptReplicationOneBlocks.longValue() >= 0 :
350	          "Number of corrupt blocks with replication factor 1 " +
351	              "should be non-negative";
352	    }
353	    return removedBlock;
354	  }
355	
356	  /**
357	   * Remove a block from the low redundancy queues.
358	   *
359	   * The priLevel parameter is a hint of which queue to query
360	   * first: if negative or &gt;= {@link #LEVEL} this shortcutting
361	   * is not attmpted.
362	   *
363	   * If the block is not found in the nominated queue, an attempt is made to
364	   * remove it from all queues.
365	   *
366	   * <i>Warning:</i> This is not a synchronized method.
367	   * @param block block to remove
368	   * @param priLevel expected privilege level
369	   * @return true if the block was found and removed from one of the priority
370	   *         queues
371	   */
372	  boolean remove(BlockInfo block, int priLevel) {
373	    return remove(block, priLevel, block.getReplication());
374	  }
375	
376	  boolean remove(BlockInfo block, int priLevel, int oldExpectedReplicas) {
377	    if(priLevel >= 0 && priLevel < LEVEL
378	        && priorityQueues.get(priLevel).remove(block)) {
379	      NameNode.blockStateChangeLog.debug(
380	          "BLOCK* NameSystem.LowRedundancyBlock.remove: Removing block {}"
381	              + " from priority queue {}",
382	          block, priLevel);
383	      decrementBlockStat(block, priLevel, oldExpectedReplicas);
384	      return true;
385	    } else {
386	      // Try to remove the block from all queues if the block was
387	      // not found in the queue for the given priority level.
388	      boolean found = false;
389	      for (int i = 0; i < LEVEL; i++) {
390	        if (i != priLevel && priorityQueues.get(i).remove(block)) {
391	          NameNode.blockStateChangeLog.debug(
392	              "BLOCK* NameSystem.LowRedundancyBlock.remove: Removing block" +
393	                  " {} from priority queue {}", block, i);
394	          decrementBlockStat(block, i, oldExpectedReplicas);
395	          found = true;
396	        }
397	      }
398	      return found;
399	    }
400	  }
401	
402	  private void decrementBlockStat(BlockInfo blockInfo, int priLevel,
403	      int oldExpectedReplicas) {
404	    if (blockInfo.isStriped()) {
405	      lowRedundancyECBlockGroups.decrement();
406	      if (priLevel == QUEUE_WITH_CORRUPT_BLOCKS) {
407	        corruptECBlockGroups.decrement();
408	      }
409	      if (priLevel == QUEUE_HIGHEST_PRIORITY) {
410	        highestPriorityLowRedundancyECBlocks.decrement();
411	      }
412	    } else {
413	      lowRedundancyBlocks.decrement();
414	      if (priLevel == QUEUE_WITH_CORRUPT_BLOCKS) {
415	        corruptBlocks.decrement();
416	        if (oldExpectedReplicas == 1) {
417	          corruptReplicationOneBlocks.decrement();
418	          assert corruptReplicationOneBlocks.longValue() >= 0 :
419	              "Number of corrupt blocks with replication factor 1 " +
420	                  "should be non-negative";
421	        }
422	      }
423	      if (priLevel == QUEUE_HIGHEST_PRIORITY) {
424	        highestPriorityLowRedundancyReplicatedBlocks.decrement();
425	      }
426	    }
427	  }
428	
429	  /**
430	   * Recalculate and potentially update the priority level of a block.
431	   *
432	   * If the block priority has changed from before an attempt is made to
433	   * remove it from the block queue. Regardless of whether or not the block
434	   * is in the block queue of (recalculate) priority, an attempt is made
435	   * to add it to that queue. This ensures that the block will be
436	   * in its expected priority queue (and only that queue) by the end of the
437	   * method call.
438	   * @param block a low redundancy block
439	   * @param curReplicas current number of replicas of the block
440	   * @param outOfServiceReplicas  the number of out-of-service replicas
441	   * @param curExpectedReplicas expected number of replicas of the block
442	   * @param curReplicasDelta the change in the replicate count from before
443	   * @param expectedReplicasDelta the change in the expected replica count
444	   *        from before
445	   */
446	  synchronized void update(BlockInfo block, int curReplicas,
447	      int readOnlyReplicas, int outOfServiceReplicas,
448	      int curExpectedReplicas,
449	      int curReplicasDelta, int expectedReplicasDelta) {
450	    int oldReplicas = curReplicas-curReplicasDelta;
451	    int oldExpectedReplicas = curExpectedReplicas-expectedReplicasDelta;
452	    int curPri = getPriority(block, curReplicas, readOnlyReplicas,
453	        outOfServiceReplicas, curExpectedReplicas);
454	    int oldPri = getPriority(block, oldReplicas, readOnlyReplicas,
455	        outOfServiceReplicas, oldExpectedReplicas);
456	    if(NameNode.stateChangeLog.isDebugEnabled()) {
457	      NameNode.stateChangeLog.debug("LowRedundancyBlocks.update " +
458	        block +
459	        " curReplicas " + curReplicas +
460	        " curExpectedReplicas " + curExpectedReplicas +
461	        " oldReplicas " + oldReplicas +
462	        " oldExpectedReplicas  " + oldExpectedReplicas +
463	        " curPri  " + curPri +
464	        " oldPri  " + oldPri);
465	    }
466	    // oldPri is mostly correct, but not always. If not found with oldPri,
467	    // other levels will be searched until the block is found & removed.
468	    remove(block, oldPri, oldExpectedReplicas);
469	    if(add(block, curPri, curExpectedReplicas)) {
470	      NameNode.blockStateChangeLog.debug(
471	          "BLOCK* NameSystem.LowRedundancyBlock.update: {} has only {} "
472	              + "replicas and needs {} replicas so is added to "
473	              + "neededReconstructions at priority level {}",
474	          block, curReplicas, curExpectedReplicas, curPri);
475	
476	    }
477	  }
478	
479	  /**
480	   * Get a list of block lists without sufficient redundancy. The index of
481	   * block lists represents its replication priority. Iterates each block list
482	   * in priority order beginning with the highest priority list. Iterators use
483	   * a bookmark to resume where the previous iteration stopped. Returns when
484	   * the block count is met or iteration reaches the end of the lowest priority
485	   * list, in which case bookmarks for each block list are reset to the heads
486	   * of their respective lists.
487	   *
488	   * @param blocksToProcess - number of blocks to fetch from low redundancy
489	   *          blocks.
490	   * @return Return a list of block lists to be replicated. The block list
491	   *         index represents its redundancy priority.
492	   */
493	  synchronized List<List<BlockInfo>> chooseLowRedundancyBlocks(
494	      int blocksToProcess) {
495	    return chooseLowRedundancyBlocks(blocksToProcess, false);
496	  }
497	
498	  /**
499	   * Get a list of block lists without sufficient redundancy. The index of
500	   * block lists represents its replication priority. Iterates each block list
501	   * in priority order beginning with the highest priority list. Iterators use
502	   * a bookmark to resume where the previous iteration stopped. Returns when
503	   * the block count is met or iteration reaches the end of the lowest priority
504	   * list, in which case bookmarks for each block list are reset to the heads
505	   * of their respective lists.
506	   * If a block is deleted (has invalid bcId), it will be removed from the low
507	   * redundancy queues.
508	   *
509	   * @param blocksToProcess - number of blocks to fetch from low redundancy
510	   *          blocks.
511	   * @param resetIterators - After gathering the list of blocks reset the
512	   *           position of all queue iterators to the head of the queue so
513	   *           subsequent calls will begin at the head of the queue
514	   * @return Return a list of block lists to be replicated. The block list
515	   *         index represents its redundancy priority.
516	   */
517	  synchronized List<List<BlockInfo>> chooseLowRedundancyBlocks(
518	      int blocksToProcess, boolean resetIterators) {
519	    final List<List<BlockInfo>> blocksToReconstruct = new ArrayList<>(LEVEL);
520	
521	    int count = 0;
522	    int priority = 0;
523	    HashSet<BlockInfo> toRemove = new HashSet<>();
524	    for (; count < blocksToProcess && priority < LEVEL; priority++) {
525	      // Go through all blocks that need reconstructions with current priority.
526	      // Set the iterator to the first unprocessed block at this priority level
527	      // We do not want to skip QUEUE_WITH_CORRUPT_BLOCKS because we still need
528	      // to look for deleted blocks if any.
529	      final boolean inCorruptLevel = (QUEUE_WITH_CORRUPT_BLOCKS == priority);
530	      final Iterator<BlockInfo> i = priorityQueues.get(priority).getBookmark();
531	      final List<BlockInfo> blocks = new LinkedList<>();
532	      if (!inCorruptLevel) {
533	        blocksToReconstruct.add(blocks);
534	      }
535	      for(; count < blocksToProcess && i.hasNext(); count++) {
536	        BlockInfo block = i.next();
537	        if (block.isDeleted()) {
538	          toRemove.add(block);
539	          continue;
540	        }
541	        if (!inCorruptLevel) {
542	          blocks.add(block);
543	        }
544	      }
545	      for (BlockInfo bInfo : toRemove) {
546	        remove(bInfo, priority);
547	      }
548	      toRemove.clear();
549	    }
550	
551	    if (priority == LEVEL || resetIterators) {
552	      // Reset all bookmarks because there were no recently added blocks.
553	      for (LightWeightLinkedSet<BlockInfo> q : priorityQueues) {
554	        q.resetBookmark();
555	      }
556	    }
557	
558	    return blocksToReconstruct;
559	  }
560	
561	  /** Returns an iterator of all blocks in a given priority queue. */
562	  synchronized Iterator<BlockInfo> iterator(int level) {
563	    return priorityQueues.get(level).iterator();
564	  }
565	
566	  /** Return an iterator of all the low redundancy blocks. */
567	  @Override
568	  public synchronized Iterator<BlockInfo> iterator() {
569	    final Iterator<LightWeightLinkedSet<BlockInfo>> q = priorityQueues.iterator();
570	    return new Iterator<BlockInfo>() {
571	      private Iterator<BlockInfo> b = q.next().iterator();
572	
573	      @Override
574	      public BlockInfo next() {
575	        hasNext();
576	        return b.next();
577	      }
578	
